        val d = repo.findMemberGroup(admin)!!
        assertEquals(Pricing.Free, d.pricing)
        assertEquals("g1a2b3c4d5", d.groupId)
    }

    @Test
    fun findMemberGroupReturnsNullForUngrouped() {
        assertNull(repo.findMemberGroup(ungrouped))
    }
