package dev.task.member.api

import com.fasterxml.jackson.annotation.JsonFormat
import com.fasterxml.jackson.annotation.JsonInclude
import java.time.LocalDateTime

@JsonInclude(JsonInclude.Include.NON_NULL)
data class MemberListResponse(val members: List<MemberSummary>, val page: PageInfo? = null, val cursor: CursorInfo? = null)

// group/permission null must be serialized (class-level NON_NULL on the wrapper does not apply here)
data class MemberSummary(val id: String, val name: String, val group: String?, val permission: Permission?)

data class PageInfo(val number: Int, val size: Int, val totalElements: Long, val totalPages: Int)

data class CursorInfo(val next: String?, val hasNext: Boolean)

data class MemberDetailResponse(
    val id: String,
    val name: String,
    val email: String,
    val address: String,
    @field:JsonFormat(pattern = "yyyy-MM-dd HH:mm") val registeredDate: LocalDateTime,
    val group: MemberGroupInfo?,
)

data class MemberGroupInfo(
    val id: String,
    val name: String,
    @field:JsonFormat(pattern = "yyyy-MM-dd HH:mm") val registeredDate: LocalDateTime,
    val pricing: Pricing,
    val permission: Permission,
)
                200,
                """{"groups":[
                  {"groupId":"g000000001","groupName":"Alpha","totalMemberCount":3,
                   "members":[{"memberId":"a000000001","permission":"Admin"},{"memberId":"x000000009","permission":"Viewer"}]},
                  {"groupId":"g000000002","groupName":"Beta","totalMemberCount":1,
                   "members":[{"memberId":"b000000002","permission":"Editor"}]}]}""",
            ),
        )
        val result = gateway.findSummaries(listOf("a000000001", "a000000001", "b000000002"))
        assertEquals(
            mapOf(
                "a000000001" to MemberGroupSummary("Alpha", Permission.Admin),
                "b000000002" to MemberGroupSummary("Beta", Permission.Editor),
            ),
            result,
        )
        assertEquals(1, requests)
    }

    @Test
    fun notFoundWithCodeReturnsNullDetail() = within4s {
        enqueue(problem(404, "MEMBER_GROUP_NOT_FOUND"))
        assertNull(gateway.findDetail("a000000001"))
        assertEquals(1, requests)
    }
}

